using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class CADBridgeTests {
  static void Check(bool v,string name){if(!v)throw new Exception("CAD integration: "+name);}static void Near(double a,double b,string name){Check(Math.Abs(a-b)<1e-5*Math.Max(1,Math.Abs(b)),name);}
  public static void Run(CADKernel kernel,string folder){var doc=new CADDocument();var box=CADTools.Feature("box");doc.Features.Add(box);var native=kernel.Run(doc,"native");var body=native.Bodies[0];body.ReadMesh();string preview=CADMeshCodec.Encode(body.Display);Near(CADMeshCodec.Decode(preview).SignedVolume(),24000,"compressed preview roundtrip");var project=new MechanismProject();var part=project.Add("block");part.NativeStep=native.Step;part.NativeProject=doc.Serialize();part.NativePreview=preview;part.NativeVolume=body.Volume;part.NativeCentre=body.Center;part.X=100;part.Y=30;part.Z=5;part.Angle=90;var build=MechanismCad.Build(project);Check(build.Valid,"native mechanism builds");var p=build.Parts.Single();Near(p.Volume(),24000,"exact mechanism volume");var center=p.Placement.Transform(RobotBuild.Centre(p));Near(center.X,85,"native mechanism rotation then translation X");Near(center.Y,50,"native mechanism rotation then translation Y");Near(center.Z,15,"native mechanism translation Z");string path=Path.Combine(folder,"native-mechanism.step");StepExport.Write(build,path);var back=kernel.Run(CADDocument.ImportStep(File.ReadAllBytes(path),"mixed"));Near(back.Bodies[0].Center[0],85,"mechanism STEP placement X");Near(back.Bodies[0].Center[1],50,"mechanism STEP placement Y");var normal=project.Add("block");normal.X=-100;build=MechanismCad.Build(project);path=Path.Combine(folder,"mixed-native-legacy.step");StepExport.Write(build,path);back=kernel.Run(CADDocument.ImportStep(File.ReadAllBytes(path),"mixed"));Near(back.Bodies.Sum(b=>b.Volume),build.Parts.Sum(x=>x.Volume()),"mixed native and legacy assembly volume");
   var robot=RobotDocument.Example();var original=RobotCad.Build(robot);var e=original.Entries.Values.First(x=>x.Category=="Корпус"&&x.Shape!=null);var edit=new RobotBodyEdit{PartId=e.Id,Shape=e.Shape.CloneShape(),NativeStep=native.Step,NativeProject=doc.Serialize(),NativePreview=preview,NativeVolume=body.Volume,NativeCentre=body.Center,NativeShift=new[]{2.0,3.0,4.0}};robot.BodyEdits.Add(edit);var rb=RobotCad.Build(robot);var ne=rb.Entries[e.Id];Near(ne.Part.Volume(),24000,"robot exact native volume");Near(rb.Mass(ne),24000*ne.Density*1e-9,"robot native mass");var expected=new Point3D(20,15,10);Near((RobotBuild.Centre(ne.Part)-expected).Length,0,"robot native centroid");path=Path.Combine(folder,"native-robot-body.step");StepExport.Write(rb.ForExport(false,e.Id),path);back=kernel.Run(CADDocument.ImportStep(File.ReadAllBytes(path),"robot"));var world=ne.Part.Placement.Transform(expected);Near(back.Bodies[0].Center[0],world.X,"robot native STEP world X");Near(back.Bodies[0].Center[1],world.Y,"robot native STEP world Y");Near(back.Bodies[0].Center[2],world.Z,"robot native STEP world Z");
  }
 }
}
